create type public.staff_role as enum ('admin','staff','viewer');
create table public.profiles(id uuid primary key references auth.users on delete cascade, role staff_role not null default 'staff', active boolean not null default true);
create table public.projects(id uuid primary key default gen_random_uuid(), code text unique not null, title text not null, predominant_question text not null, answer_summary text, status text not null default 'exploring', owner_id uuid references public.profiles, created_at timestamptz not null default now());
create table public.decisions(id uuid primary key default gen_random_uuid(), project_id uuid not null references public.projects on delete cascade, question text not null, decision text, alternatives jsonb not null default '[]', consequences jsonb not null default '[]', escape_route text, evidence text, created_by uuid not null default auth.uid() references public.profiles, created_at timestamptz not null default now());
create table public.documents(id uuid primary key default gen_random_uuid(), project_id uuid references public.projects on delete set null, storage_path text unique not null, title text not null, tags text[] not null default '{}', extracted_text text, uploaded_by uuid not null default auth.uid() references public.profiles, created_at timestamptz not null default now());
create table public.templates(id uuid primary key default gen_random_uuid(), title text not null, kind text not null, body jsonb not null, version int not null default 1, active boolean not null default true);
create table public.ai_usage(id bigint generated always as identity primary key, client_hash text not null, model text not null, created_at timestamptz not null default now());
alter table public.profiles enable row level security;alter table public.projects enable row level security;alter table public.decisions enable row level security;alter table public.documents enable row level security;alter table public.templates enable row level security;
create function public.is_staff() returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from profiles where id=auth.uid() and active and role in ('admin','staff'))$$;
create function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from profiles where id=auth.uid() and active and role='admin')$$;
create policy "profiles read" on public.profiles for select to authenticated using(id=auth.uid() or public.is_admin());create policy "profiles admin" on public.profiles for all to authenticated using(public.is_admin()) with check(public.is_admin());
create policy "projects staff" on public.projects for all to authenticated using(public.is_staff()) with check(public.is_staff());create policy "decisions staff" on public.decisions for all to authenticated using(public.is_staff()) with check(public.is_staff());create policy "documents staff" on public.documents for all to authenticated using(public.is_staff()) with check(public.is_staff());create policy "templates read" on public.templates for select to authenticated using(public.is_staff());create policy "templates admin" on public.templates for all to authenticated using(public.is_admin()) with check(public.is_admin());
alter table public.ai_usage enable row level security;
create index ai_usage_limit on public.ai_usage(client_hash,created_at);
insert into storage.buckets(id,name,public,file_size_limit) values('vault','vault',false,26214400) on conflict do nothing;create policy "vault read" on storage.objects for select to authenticated using(bucket_id='vault' and public.is_staff());create policy "vault add" on storage.objects for insert to authenticated with check(bucket_id='vault' and public.is_staff());create policy "vault delete" on storage.objects for delete to authenticated using(bucket_id='vault' and public.is_admin());
